function destroyCircular(from: object, seen: any[]) {	
    const to = Array.isArray(from) ? [] : {};	

    seen.push(from);	

    for (const key of Object.keys(from)) {	
        const value = (from as any)[key];	

        if (typeof value === 'function') {
            continue;	
        }

        if (!value || typeof value !== 'object') {	
            (to as any)[key] = value;	
            continue;	
        }	

        if (!seen.includes((from as any)[key])) {	
            (to as any)[key] = destroyCircular((from as any)[key], seen.slice());	
            continue;	
        }	

        (to as any)[key] = '[Circular]';	
    }	

    const commonProperties = ['name', 'message', 'stack', 'code'];	

    for (const property of commonProperties) {	
        if (typeof (from as any)[property] === 'string') {	
            (to as any)[property] = (from as any)[property];	
        }	
    }	

    return to;	
}

export function serialise(value: any) {	
    if (typeof value === 'object') {	
        return destroyCircular(value, []);	
    }	

    // People sometimes throw things besides Error objects…	
    if (typeof value === 'function') {	
        // JSON.stringify discards functions. We do too, unless a function is thrown directly.	
        return `[Function: ${(value.name || 'anonymous')}]`;	
    }	

    value.isSerialised = true;	

    return value;	
}